/* Original assessment script 1 */

  // Paste your full 'New Deployment' macro URL inside the quotes below
  const dh_BACKEND_URL = "https://script.google.com/macros/s/AKfycbxlpbXKOn-SXZKUGwTsVez9sJZ-vfoiqL7fkhySJJwgiHdyjtsvZzVRVujkTTaTaT-G/exec";

  let dh_allServerQuestions = []; 
  let dh_activeQuestions = [];    
  let dh_userAnswers = {};        
  let dh_serverEvaluations = {};  
  let dh_currentIndex = 0;
  let dh_timerInterval = null;
  let dh_totalQuizSeconds = 0;

  async function dh_loadMetadata() {
    const cls = document.getElementById("dh-class-select").value;
    const chSelect = document.getElementById("dh-chapter-select");
    const stSelect = document.getElementById("dh-set-select");

    if(!cls) return;
    if(chSelect) chSelect.innerHTML = "<option>Loading chapters...</option>";

    const res = await fetch(`${dh_BACKEND_URL}?action=getMetadata&class=${cls}`);
    const meta = await res.json();

    if(chSelect) {
      chSelect.innerHTML = "<option value=''>-- Choose Chapter --</option>" + 
        meta.chapters.map(i => `<option value="${i}">${i}</option>`).join('');
      chSelect.disabled = false;
    }
    if(stSelect) { stSelect.disabled = true; stSelect.innerHTML = ""; }
  }

  async function dh_loadSets() {
    const cls = document.getElementById("dh-class-select").value;
    const ch = document.getElementById("dh-chapter-select").value;
    const stSelect = document.getElementById("dh-set-select");
    if (!ch || !stSelect) return;
    stSelect.disabled = true;
    stSelect.innerHTML = '<option value="">Loading sets...</option>';
    try {
      const res = await fetch(`${dh_BACKEND_URL}?action=getMetadata&class=${encodeURIComponent(cls)}&chapter=${encodeURIComponent(ch)}`);
      if (!res.ok) throw new Error("Metadata HTTP " + res.status);
      const meta = await res.json();
      const sets = [...new Set((meta.sets || []).filter(Boolean).filter(s => s !== "ALL"))];
      stSelect.replaceChildren(new Option("-- Choose Set --", ""));
      stSelect.add(new Option("ALL (All Sets)", "ALL"));
      sets.forEach(set => stSelect.add(new Option(set, set)));
      stSelect.disabled = false;
      stSelect.value = sets.length === 1 ? sets[0] : "ALL";
      await dh_filterPoolHint();
    } catch (err) {
      stSelect.innerHTML = '<option value="">Unable to load sets</option>';
      document.getElementById("dh-available-pool-hint").textContent = "Could not load sets.";
      console.error("Set metadata:", err);
    }
  }

  let dh_poolRequestToken = 0;
  async function dh_filterPoolHint() {
    const cls = document.getElementById("dh-class-select").value;
    const ch = document.getElementById("dh-chapter-select").value;
    const setSelect = document.getElementById("dh-set-select");
    const st = setSelect.value;
    const hintEl = document.getElementById("dh-available-pool-hint");
    const poolInput = document.getElementById("dh-student-pool-count");
    const token = ++dh_poolRequestToken;
    dh_allServerQuestions = [];
    if (!cls || !ch || !st) return;
    if (hintEl) hintEl.textContent = "Synchronizing counts with server...";
    try {
      const sets = st === "ALL"
        ? Array.from(setSelect.options).map(o => o.value).filter(v => v && v !== "ALL")
        : [st];
      if (!sets.length) throw new Error("No sets available");
      const groups = await Promise.all(sets.map(async set => {
        const url = `${dh_BACKEND_URL}?action=getQuestions&class=${encodeURIComponent(cls)}&chapter=${encodeURIComponent(ch)}&set=${encodeURIComponent(set)}`;
        const res = await fetch(url);
        if (!res.ok) throw new Error("Questions HTTP " + res.status);
        const data = await res.json();
        if (!Array.isArray(data.questions)) throw new Error("Invalid question response for " + set);
        return data.questions.map(q => ({...q, mh_source_set: set}));
      }));
      if (token !== dh_poolRequestToken || setSelect.value !== st) return;
      dh_allServerQuestions = groups.flat();
      if (hintEl) hintEl.textContent = `Available pool: ${dh_allServerQuestions.length} questions total${st === "ALL" ? " across " + sets.length + " sets" : ""}.`;
      if (poolInput) {
        poolInput.min = 1;
        poolInput.max = Math.min(30, dh_allServerQuestions.length);
        poolInput.value = Math.min(10, dh_allServerQuestions.length);
      }
    } catch (err) {
      if (hintEl) hintEl.textContent = "Sync failed. Re-select options.";
      console.error("Question pool:", err);
    }
  }



/* Original assessment script 2 */

  function dh_startQuiz(isRestoring = false) {
    const nameInput = document.getElementById("dh-student-name");
    const emailInput = document.getElementById("dh-student-email");
    const poolInput = document.getElementById("dh-student-pool-count");
    const st = document.getElementById("dh-set-select").value;
    const poolCount = poolInput ? parseInt(poolInput.value) : 0;

    if (!isRestoring) {
      if(!nameInput.value.trim() || !emailInput.value.trim()) { alert("Please enter your Student Name and Email Address."); return; }
      if(!st) { alert("Please confirm drop-down configuration filters are selected."); return; }
      // Locate this validation statement section inside Part 3 and update the threshold bounds check:
if (poolCount < 1 || poolCount > Math.min(30, dh_allServerQuestions.length)) {
  alert(`Please enter a question count between 1 and ${Math.min(30, dh_allServerQuestions.length)}.`);
  return;
}
      if (!dh_allServerQuestions || dh_allServerQuestions.length === 0) { alert("Syncing databank keys. Wait a moment and try again."); return; }
      if (poolCount < 1 || poolCount > dh_allServerQuestions.length) { alert(`Enter a question count between 1 and ${dh_allServerQuestions.length}.`); return; }

      // --- RANDOM SELECTION SHUFFLE PIPELINE ---
      let poolScramblerArray = [...dh_allServerQuestions];
      for (let i = poolScramblerArray.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [poolScramblerArray[i], poolScramblerArray[j]] = [poolScramblerArray[j], poolScramblerArray[i]];
      }
      dh_activeQuestions = poolScramblerArray.slice(0, poolCount);
      dh_totalQuizSeconds = dh_activeQuestions.length * 120;
      dh_currentIndex = 0; 

      localStorage.setItem("dh_quiz_active_state", "true");
      localStorage.setItem("dh_student_name", nameInput.value.trim());
      localStorage.setItem("dh_student_email", emailInput.value.trim());
      localStorage.setItem("dh_class", document.getElementById("dh-class-select").value);
      localStorage.setItem("dh_chapter", document.getElementById("dh-chapter-select").value);
      localStorage.setItem("dh_set", st);
      localStorage.setItem("dh_active_questions", JSON.stringify(dh_activeQuestions));
      localStorage.setItem("dh_current_index", dh_currentIndex.toString());
      localStorage.setItem("dh_timer_end_timestamp", (Date.now() + (dh_totalQuizSeconds * 1000)).toString());
      // Persist the assessment start time so elapsed time survives page refreshes.
      localStorage.setItem("dh_assessment_started_at", Date.now().toString());
    }

    
  
    
    const configDashboard = document.getElementById("dh-quiz-config-dashboard");
    if (configDashboard) {
      configDashboard.style.display = "none";
      configDashboard.setAttribute("aria-hidden", "true");
    }
    document.getElementById("dh-credential-zone").style.display = "none";
    document.getElementById("dh-q-Select").style.display = "none";

    document.getElementById("dh-timer-box").style.display = "flex";
    if (window.dhRefreshFloatingTimerPosition) window.dhRefreshFloatingTimerPosition();
    document.getElementById("dh-question-progress-panel").style.display = "block";
    document.getElementById("dh-segmented-tracker").style.display = "block";
    document.body.classList.add("dh-quiz-active");
    document.getElementById("dh-quiz-nav-panel").style.display = "flex";
    document.getElementById("dh-final-submit-zone").style.display = "block";

    document.body.classList.remove("dh-quiz-submitted");
    const submitZone = document.getElementById("dh-final-submit-zone");
    if (submitZone) submitZone.querySelectorAll("button, input").forEach(btn => { btn.disabled = false; btn.removeAttribute("aria-disabled"); });
    dh_startCountdown(); dh_buildTrackerSegments(); dh_renderActiveCard();
  }

  function dh_renderActiveCard() {
    if(!dh_activeQuestions || dh_activeQuestions.length === 0) return;
    const q = dh_activeQuestions[dh_currentIndex];
    const container = document.getElementById("dh-dynamic-quiz-card-space");
    if(!q || !container) return;
    
    container.style.display = "block";
    localStorage.setItem("dh_current_index", dh_currentIndex.toString());
    dh_updateQuestionProgress();

    let qImgsHtml = "";
    if (q.images && q.images.length > 0) {
      q.images.forEach(imgUrl => {
        if(imgUrl.trim() !== "") {
          qImgsHtml += `<img src="${imgUrl}" alt=""/>`;
        }
      });
    }

    const savedAns = dh_userAnswers[dh_currentIndex] || "";
    const isEvaluated = dh_serverEvaluations[dh_currentIndex] ? true : false;

    const labels = ["A", "B", "C", "D"];
    let optionsHtml = q.options.map((opt, idx) => {
      const isChecked = (savedAns === labels[idx]) ? "checked" : "";
      const optImgHtml = opt.img ? `<img src="${opt.img}" alt="Option Graphic" style="max-width:150px; height:auto; display:block; margin-top:6px; border:1px solid #eee;"/>` : "";
      const disabledAttr = isEvaluated ? "disabled" : "";

	return `
        <label class="dh-option-label option-label">
          <input type="radio" name="dh-dynamic-opts" value="${labels[idx]}" ${isChecked} ${disabledAttr} onclick="dh_saveAnswer('${labels[idx]}')" style="display: none !important;">
          <span class="option-letter">${labels[idx]}</span>
          <span class="option-text">${opt.text}</span>
          ${optImgHtml}
        </label>
      `;
    }).join('');

    let feedbackHtml = "";
    let accordionClass = "solution-accordion locked";
    let accordionToggleAttrs = "disabled";
    let solutionInnerContent = "<strong>Step-by-step Solution:</strong><br />Locked until assessment submission.";

    if (isEvaluated) {
      const evalData = dh_serverEvaluations[dh_currentIndex];
      accordionClass = "solution-accordion";
      accordionToggleAttrs = "";
      solutionInnerContent = `<strong>Step-by-step Solution:</strong><br />${evalData.solution}`;
      
      if(evalData.correct) {
        feedbackHtml = `<div style="color:green; font-weight:bold; margin:10px 0;">🎉 Correct Answer!</div>`;
      } else {
        feedbackHtml = `<div style="color:red; font-weight:bold; margin:10px 0;">❌ Incorrect choice.</div>`;
      }
    }

    // FIXED CLASS LABELS: Converted into standard namespaces .quiz-card and .q-text so your shortcode regex engine triggers cleanly
    container.innerHTML = `
      <div class="dh-quiz-card quiz-card active" style="padding:15px; border:1px solid #eee; border-radius:6px; background:#fff;"> 
        <div class="dh-question-heading">
          <span class="dh-question-number">Q${dh_currentIndex + 1}</span>
          <div class="dh-question-body"><span class="q-text">${q.question}</span>
          ${ q.codeSnippet && q.codeSnippet.trim() !== '' ? `<div class="code-box" style="margin-top: 15px;">${q.codeSnippet}</div>` : '' }</div>
  	  	</div>  
        <div class="dh-question-images">${qImgsHtml}</div>
        ${q.year ? `<div class="dh-year-badge-row"><span class="year-badge" title="Question year">${q.year}</span></div>` : ''}
        <div class="options-group">${optionsHtml}</div>   
        ${feedbackHtml}
        <div class="${accordionClass}" style="margin-top:15px; border:1px solid #ccc; border-radius:4px; padding:8px;">
          <button class="accordion-toggle" ${accordionToggleAttrs} onclick="dh_toggleAccordion(this)" type="button" style="width:100%; text-align:left; background:none; border:none; font-weight:bold; cursor:pointer;">
            ${isEvaluated ? "View Detailed Solution" : "View Detailed Solution (Locked)"}
          </button>
          <div class="accordion-content" style="display:none; margin-top:8px; padding-top:8px; border-top:1px solid #eee;">
            <div class="solution-inner">${solutionInnerContent}</div>
          </div>
        </div>
      </div>
    `;

    // CRITICAL ENGINE TRIGGER: Runs asset vector lookup and compiles MathJax formulas seamlessly
    if (typeof injectGitHubAssets === "function") {
      injectGitHubAssets();
    }

    if (window.MathJax && typeof window.MathJax.typesetPromise === "function") {
      window.MathJax.typesetPromise();
    }
    dh_updateTrackerUI();
    dh_syncNavigationButtons();
  }


/* Original assessment script 3 */

  window.mhV3Ready(() => {
    const floatingTimer = document.getElementById("dh-timer-box");
    floatingTimer.style.display = "none";
    let timerFloatThreshold = 0;
    const updateFloatingTimer = () => {
      if (!floatingTimer || floatingTimer.style.display === "none" || document.body.classList.contains("dh-quiz-submitted")) return;
      const shouldFloat = window.scrollY > timerFloatThreshold;
      floatingTimer.classList.toggle("dh-timer-floating", shouldFloat);
    };
    const measureTimerPosition = () => {
      if (!floatingTimer) return;
      const wasFloating = floatingTimer.classList.contains("dh-timer-floating");
      floatingTimer.classList.remove("dh-timer-floating");
      timerFloatThreshold = floatingTimer.getBoundingClientRect().top + window.scrollY - 12;
      if (wasFloating) floatingTimer.classList.add("dh-timer-floating");
      updateFloatingTimer();
    };
    window.addEventListener("scroll", updateFloatingTimer, { passive: true });
    window.addEventListener("resize", measureTimerPosition);
    window.dhRefreshFloatingTimerPosition = measureTimerPosition;
    window.dhStopFloatingTimer = () => floatingTimer && floatingTimer.classList.remove("dh-timer-floating");
    document.getElementById("dh-question-progress-panel").style.display = "none";
    document.getElementById("dh-segmented-tracker").style.display = "none";
    document.getElementById("dh-quiz-nav-panel").style.display = "none";
    document.getElementById("dh-final-submit-zone").style.display = "none";

    const wrappers = document.querySelectorAll('.quiz-main-system-wrapper, .dh-quiz-container');
    wrappers.forEach(el => el.style.display = 'block');

    if (localStorage.getItem("dh_quiz_active_state") === "true") {
      const savedEndTime = parseInt(localStorage.getItem("dh_timer_end_timestamp")) || 0;
      const calculatedRemainingSeconds = Math.floor((savedEndTime - Date.now()) / 1000);

      if (calculatedRemainingSeconds <= 0 || !localStorage.getItem("dh_active_questions")) {
        localStorage.clear(); console.log("Expired cache variables wiped cleanly.");
      } else {
        dh_restoreSessionState(); dh_totalQuizSeconds = calculatedRemainingSeconds; dh_startQuiz(true); 
      }
    }
  });

  function dh_restoreSessionState() {
    document.getElementById("dh-student-name").value = localStorage.getItem("dh_student_name") || "";
    document.getElementById("dh-student-email").value = localStorage.getItem("dh_student_email") || "";
    dh_activeQuestions = JSON.parse(localStorage.getItem("dh_active_questions")) || [];
    dh_userAnswers = JSON.parse(localStorage.getItem("dh_user_answers")) || {};
    dh_currentIndex = parseInt(localStorage.getItem("dh_current_index")) || 0;
  }

  function dh_saveAnswer(letter) {
    if(dh_serverEvaluations[dh_currentIndex]) return;
    dh_userAnswers[dh_currentIndex] = letter;
    localStorage.setItem("dh_user_answers", JSON.stringify(dh_userAnswers)); 
    dh_updateTrackerUI();
  }

  function dh_clearActiveSelection() {
    if(dh_serverEvaluations[dh_currentIndex]) return;
    delete dh_userAnswers[dh_currentIndex];
    localStorage.setItem("dh_user_answers", JSON.stringify(dh_userAnswers));
    const radios = document.getElementsByName("dh-dynamic-opts");
    for(let r of radios) r.checked = false;
    dh_updateTrackerUI();
  }

  // Keep Previous/Next controls synchronized with the active card.
  function dh_syncNavigationButtons() {
    const panel = document.getElementById("dh-quiz-nav-panel");
    if (!panel) return;
    const lastIndex = Math.max(0, dh_activeQuestions.length - 1);
    panel.querySelectorAll('button, input[type="button"]').forEach(btn => {
      const handler = btn.getAttribute('onclick') || '';
      const text = (btn.textContent || btn.value || '').trim().toLowerCase();
      const isPrev = /dh_navigateQuestion\s*\(\s*-1\s*\)/.test(handler) ||
        /^(prev|previous|‹|←)$/.test(text);
      const isNext = /dh_navigateQuestion\s*\(\s*1\s*\)/.test(handler) ||
        /^(next|›|→)$/.test(text);
      if (!isPrev && !isNext) return;
      const disabled = !dh_activeQuestions.length || (isPrev ? dh_currentIndex === 0 : dh_currentIndex >= lastIndex);
      btn.disabled = disabled;
      btn.setAttribute('aria-disabled', String(disabled));
      btn.style.opacity = disabled ? '0.42' : '';
      btn.style.cursor = disabled ? 'not-allowed' : '';
    });
  }

  function dh_lockSubmitButton() {
    const zone = document.getElementById('dh-final-submit-zone');
    if (!zone) return;
    zone.querySelectorAll('button, input[type="button"], input[type="submit"]').forEach(btn => {
      btn.disabled = true;
      btn.setAttribute('aria-disabled', 'true');
    });
  }

  function dh_navigateQuestion(direction) {
    if (!dh_activeQuestions || dh_activeQuestions.length === 0) return;
    dh_currentIndex += direction;
    if(dh_currentIndex < 0) dh_currentIndex = 0;
    if(dh_currentIndex >= dh_activeQuestions.length) dh_currentIndex = dh_activeQuestions.length - 1;
    dh_renderActiveCard();
  }

  function dh_updateQuestionProgress() {
    const total = dh_activeQuestions ? dh_activeQuestions.length : 0;
    if (!total) return;
    const current = Math.min(total, Math.max(1, dh_currentIndex + 1));
    const percent = Math.round((current / total) * 100);
    const label = document.getElementById("dh-question-progress-label");
    const pct = document.getElementById("dh-question-progress-percent");
    const fill = document.getElementById("dh-question-progress-fill");
    const track = fill ? fill.parentElement : null;
    if (label) label.textContent = `Question ${current} of ${total}`;
    if (pct) pct.textContent = `${percent}%`;
    if (fill) fill.style.width = `${percent}%`;
    if (track) track.setAttribute("aria-valuenow", String(percent));
  }

  function dh_buildTrackerSegments() {
    if (!dh_activeQuestions || !dh_activeQuestions.length) return;
    const total = dh_activeQuestions.length;
    document.getElementById("dh-seg-total-count").textContent = total;
    const bar = document.getElementById("dh-segmented-bar-wrapper");
    bar.replaceChildren();
    bar.classList.toggle("dh-two-rows", total > 15);
    bar.style.setProperty("--dh-tracker-count", String(total > 15 ? Math.ceil(total / 2) : total));
    dh_activeQuestions.forEach((_, index) => {
      const block = document.createElement("button");
      block.type = "button";
      block.id = `dh-seg-block-${index}`;
      block.className = "dh-tracker-number";
      block.textContent = String(index + 1);
      block.title = `Go to question ${index + 1}`;
      block.setAttribute("aria-label", `Go to question ${index + 1}`);
      bar.appendChild(block);
    });
    dh_updateTrackerUI();
  }

  function dh_updateTrackerUI() {
    if (!dh_activeQuestions || !dh_activeQuestions.length) return;
    let attemptedCount = 0;
    dh_activeQuestions.forEach((_, index) => {
      const block = document.getElementById(`dh-seg-block-${index}`);
      const attempted = Object.prototype.hasOwnProperty.call(dh_userAnswers, index) &&
        dh_userAnswers[index] !== null && dh_userAnswers[index] !== undefined && dh_userAnswers[index] !== '';
      if (attempted) attemptedCount++;
      if (!block) return;
      block.classList.toggle('dh-attempted', attempted);
      block.classList.toggle('dh-current', index === dh_currentIndex);
      block.setAttribute('aria-current', index === dh_currentIndex ? 'step' : 'false');
      block.title = `Question ${index + 1}: ${attempted ? 'attempted' : 'not attempted'}`;
    });
    const count = document.getElementById("dh-seg-attempted-count");
    if (count) count.textContent = attemptedCount;
  }

  function dh_toggleAccordion(btn) {
    const content = btn.nextElementSibling;
    content.style.display = (content.style.display === "none") ? "block" : "none";
  }


/* Original assessment script 4 */

  function dh_startCountdown() {
    if (dh_timerInterval) clearInterval(dh_timerInterval);
    dh_timerInterval = setInterval(() => {
      if(dh_totalQuizSeconds <= 0) {
        clearInterval(dh_timerInterval); alert("Time limits exhausted! Submitting choices automatically.");
        dh_submitAssessment(true); return;
      }
      dh_totalQuizSeconds--;
      let hrs = Math.floor(dh_totalQuizSeconds / 3600);
      let mins = Math.floor((dh_totalQuizSeconds % 3600) / 60);
      let secs = dh_totalQuizSeconds % 60;
      document.getElementById("dh-time-counter").innerText = 
        `${String(hrs).padStart(2,'0')} : ${String(mins).padStart(2,'0')} : ${String(secs).padStart(2,'0')}`;
    }, 1000);
  }

  // DYNAMIC TITLE FILE NAMER ENGINE (Pads execution timelines to prevent attempt file overrides)  function 
  function dh_triggerSecurePrint(printTargetElementId, targetFileNameString) {
    const originalDocumentTitle = document.title;
    const d = new Date();
    const pad = (n) => String(n).padStart(2, '0');
    const timestamp = d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()) + "_" + pad(d.getHours()) + pad(d.getMinutes()) + pad(d.getSeconds());

    document.title = `${targetFileNameString}_${timestamp}`;
    const printContainer = document.getElementById(printTargetElementId);
    if (!printContainer) return;

    // 1. Ensure any raw image tokens inside the container are converted to proper img tags
    if (printContainer.innerHTML.includes("picQ52") || printContainer.innerHTML.includes("picQ65")) {
      printContainer.innerHTML = printContainer.innerHTML
        .replace(/\{\[\}\{\[\}picQ52\{\]\}\{\]\}/g, '<img src="https://raw.githubusercontent.com/debasis-sahoo/maths-hub/main/images/picQ52.png" style="max-width:320px;height:auto;display:block;margin:10px auto;" />')
        .replace(/\{\[\}\{\[\}picQ65\{\]\}\{\]\}/g, '<img src="https://raw.githubusercontent.com/debasis-sahoo/maths-hub/main/images/picQ65.png" style="max-width:320px;height:auto;display:block;margin:10px auto;" />');
    }

    printContainer.classList.add("dh-print-active-target");

    // 2. Wait for images to load before calling window.print()
    const imgs = printContainer.querySelectorAll("img");
    const launchPrint = () => {
      // Small timeout to allow paint cycle to complete
      setTimeout(() => {
        window.print();
        printContainer.classList.remove("dh-print-active-target");
        document.title = originalDocumentTitle;
      }, 150);
    };

    if (imgs.length === 0) {
      launchPrint();
    } else {
      let loaded = 0;
      imgs.forEach((img) => {
        if (img.complete) {
          loaded++;
          if (loaded === imgs.length) launchPrint();
        } else {
          img.onload = img.onerror = () => {
            loaded++;
            if (loaded === imgs.length) launchPrint();
          };
        }
      });
    }
  }



/* Original assessment script 5 */

  let dh_submissionInProgress = false;
  async function dh_submitAssessment(isAutoSubmit = false) {
    if (dh_submissionInProgress || document.body.classList.contains("dh-quiz-submitted")) return;
    if (!isAutoSubmit) {
      const doubleCheck = confirm("Finalize assessment submission?");
      if (!doubleCheck) return;
    }
    dh_submissionInProgress = true;
    dh_lockSubmitButton();
    clearInterval(dh_timerInterval);

    // End the timed test, but retain question cards and navigation for post-submit solution review.
    if(document.getElementById("dh-dynamic-quiz-card-space")) document.getElementById("dh-dynamic-quiz-card-space").style.display = "block";
    if(document.getElementById("dh-quiz-nav-panel")) document.getElementById("dh-quiz-nav-panel").style.display = "none";
    if(document.getElementById("dh-final-submit-zone")) document.getElementById("dh-final-submit-zone").style.display = "none";
    if(document.getElementById("dh-timer-box")) {
      document.getElementById("dh-timer-box").style.display = "none";
      document.getElementById("dh-timer-box").classList.remove("dh-timer-floating");
    }
    document.body.classList.add("dh-quiz-submitted");
    if(document.getElementById("dh-question-progress-panel")) document.getElementById("dh-question-progress-panel").style.display = "none";
    if(document.getElementById("dh-segmented-tracker")) document.getElementById("dh-segmented-tracker").style.display = "none";

    const cls = localStorage.getItem("dh_class") || document.getElementById("dh-class-select").value;
    const chSelected = localStorage.getItem("dh_chapter") || document.getElementById("dh-chapter-select").value;
    const stSelected = localStorage.getItem("dh_set") || document.getElementById("dh-set-select").value;
    const nameInput = localStorage.getItem("dh_student_name") || document.getElementById("dh-student-name").value.trim();
    const emailInput = localStorage.getItem("dh_student_email") || document.getElementById("dh-student-email").value.trim();
    const assessmentStartedAt = parseInt(localStorage.getItem("dh_assessment_started_at"), 10) || Date.now();
    const assessmentSubmittedAt = Date.now();
    const timeTakenSeconds = Math.max(0, Math.floor((assessmentSubmittedAt - assessmentStartedAt) / 1000));
    const timeTakenFormatted = [Math.floor(timeTakenSeconds / 3600), Math.floor((timeTakenSeconds % 3600) / 60), timeTakenSeconds % 60]
      .map(n => String(n).padStart(2, "0")).join(":");
    localStorage.clear(); 

    const resultDisplay = document.getElementById("dh-quiz-result");
    resultDisplay.innerHTML = `<section class="mh-scorecard-processing" role="status" aria-live="polite" aria-atomic="true">
      <div class="mh-scorecard-processing-spinner" aria-hidden="true"></div>
      <div class="mh-scorecard-processing-kicker">MATHEMATICS HUB</div>
      <h3>Preparing Your Assessment Report</h3>
      <p class="mh-scorecard-processing-primary">Verifying your answers securely…</p>
      <p class="mh-scorecard-processing-secondary">Generating your personalised scorecard.</p>
      <p class="mh-scorecard-processing-footnote">Please wait. Your assessment is being processed.</p>
    </section>`;
    let rawScore = 0; 
    let trackingMatrix = [];

    for (let i = 0; i < dh_activeQuestions.length; i++) {
      const q = dh_activeQuestions[i];
      const selectedLetter = dh_userAnswers[i] || "Skipped";
      const skipped = selectedLetter === "Skipped";
      const labels = ["A", "B", "C", "D"];
      const chosenIndex = labels.indexOf(selectedLetter);
      const chosenText = skipped ? "" : (q.options[chosenIndex]?.text || "");

      try {
        // Also verify skipped questions, but NEVER count them as correct.
        // The Apps Script must return correctLetter and solution for blank answers.
        const response = await fetch(dh_BACKEND_URL, {
          method: "POST",
          body: JSON.stringify({
            class: cls, id: q.id, answer: chosenText,
            selectedLetter: skipped ? "" : selectedLetter
          })
        });
        if (!response.ok) throw new Error("Verification HTTP " + response.status);
        const result = await response.json();
        if (result.error) throw new Error(String(result.error));
        const correctLetter = result.correctLetter || "N/A";
        const isCorrect = !skipped && result.correct === true;
        dh_serverEvaluations[i] = {
          correct: isCorrect,
          skipped: skipped,
          solution: result.solution || "No explanation provided."
        };
        trackingMatrix.push({
          displayedNum: i + 1, actualNum: q.id,
          selectedOpt: skipped ? "Skipped" : selectedLetter,
          correctOpt: correctLetter,
          questionText: q.question,
          solutionText: result.solution || "No explanation provided."
        });
        if (isCorrect) rawScore++;
      } catch (e) {
        console.error("Question verification failed", q.id, e);
        dh_serverEvaluations[i] = {
          correct: false, skipped: skipped,
          solution: "Unable to retrieve explanation from the server."
        };
        trackingMatrix.push({
          displayedNum: i + 1, actualNum: q.id,
          selectedOpt: skipped ? "Skipped" : selectedLetter,
          correctOpt: "N/A", questionText: q.question,
          solutionText: "Verification failed. Please check the backend."
        });
      }
    }
    // Re-render the current card using its completed evaluation so the detailed solution is unlocked.
    if (typeof dh_renderActiveCard === "function") dh_renderActiveCard();
    dh_renderFinalTranscriptReportHTML(rawScore, trackingMatrix, cls, chSelected, stSelected, nameInput, emailInput, timeTakenSeconds, timeTakenFormatted);
  }


/* Original assessment script 6 */

  function dh_renderFinalTranscriptReportHTML(rawScore, trackingMatrix, cls, chSelected, stSelected, nameInput, emailInput, timeTakenSeconds = 0, timeTakenFormatted = "00:00:00") {
    const resultDisplay = document.getElementById("dh-quiz-result");
    const calculatedPercentage = Math.round((rawScore / dh_activeQuestions.length) * 100);
    const safePrintFileName = `${chSelected.replace(/[\s:]+/g, '_')}_${nameInput.replace(/[\s]+/g, '_')}`;

    // FIXED REQUIREMENT 3: Generates scorecard matrix showing strictly the option letters (A, B, C, D)
    let reportRowsHtml = trackingMatrix.map((row, idx) => {
      let finalDisplayKey = row.correctOpt; 
      const isCorrect = (dh_serverEvaluations[idx] && dh_serverEvaluations[idx].correct);

      if (finalDisplayKey === "N/A" || finalDisplayKey === "") {
        finalDisplayKey = isCorrect ? row.selectedOpt : "N/A";
      }

      const isSkipped = row.selectedOpt === "Skipped";
      const statusIcon = isSkipped
        ? `<span style="color:#64748b; font-size:15px; font-weight:bold;">○ Not Attempted</span>`
        : isCorrect
          ? `<span style="color:#16a34a; font-size:15px; font-weight:bold;">✓ Correct</span>`
          : `<span style="color:#dc2626; font-size:15px; font-weight:bold;">✗ Incorrect</span>`;

      return `
        <tr style="border-bottom: 1px solid #e2e8f0; text-align: center;">
          <td style="padding: 12px; color:#475569;">${row.displayedNum}</td>
          <td style="padding: 12px; font-weight: bold; color:${isCorrect ? '#1e293b' : '#dc2626'}; background:${isCorrect ? 'none' : '#fef2f2'};">${row.selectedOpt}</td>
          <td style="padding: 12px; font-weight: bold; color: #2563eb;">${finalDisplayKey}</td>
          <td style="padding: 12px;">${statusIcon}</td>
  </tr>`;
    }).join('');

    // Generate Full Review Cards Mapping Color Status Boxes Clear of Bank IDs
    let fullResponseReviewCardsHtml = dh_activeQuestions.map((q, idx) => {
      const userChoice = dh_userAnswers[idx] || "Skipped"; 
      const evalItem = dh_serverEvaluations[idx];
      const isSkipped = userChoice === "Skipped";
      let qImgsHtml = ""; 

      if (q.images && q.images.length > 0) {
        q.images.forEach(imgUrl => { if(imgUrl.trim() !== "") qImgsHtml += `<img src="${imgUrl}"/>`; });
      }

      let trueKeyLetter = trackingMatrix[idx] ? trackingMatrix[idx].correctOpt : "N/A"; 
      if(trueKeyLetter === "N/A" && evalItem?.correct) trueKeyLetter = userChoice;

      let parsedOptsHtml = q.options.map((opt, oIdx) => {
        const letter = ["A", "B", "C", "D"][oIdx]; 
        let style = "border:1px solid #e2e8f0; background:#fff; color:#334155;"; 
        let flag = "";

        if (letter === trueKeyLetter) { 
          style = "border:2px solid #10b981; background:#f0fdf4; color:#14532d; font-weight:bold;"; 
          flag = " <span style='color:#10b981; font-weight:bold;'>✓ (Correct Answer)</span>"; 
        } else if (letter === userChoice) { 
          style = "border:2px solid #f87171; background:#fef2f2; color:#7f1d1d; font-weight:bold;"; 
          flag = " <span style='color:#ef4444; font-weight:bold;'>✗ (Your Choice)</span>"; 
        }
        return `<div class="option-label dh-review-option ${letter === trueKeyLetter ? 'dh-review-correct' : letter === userChoice ? 'dh-review-incorrect' : 'dh-review-neutral'}" style="padding:10px; margin:6px 0; border-radius:6px; display: flex; align-items: flex-start; ${style}">
                  <span class="option-letter" style="margin-right: 15px; margin-top: 2px; flex-shrink: 0;">${letter}</span> 
                  <span style="flex: 1; line-height: 1.6;">${opt.text} ${flag}</span>
                </div>`;
      }).join('');

      return `
        <div class="dh-report-card-review" style="padding:18px; border:1px solid #e2e8f0; border-radius:8px; margin-bottom:20px; background:#fff; page-break-inside: avoid;">
          <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:12px;">
 


<div class="q-text" style="font-size:1.1em; color:#1e293b; line-height:1.5; flex:1;"><strong>Question ${ idx + 1 }:</strong> ${ q.question }</div>
 
 
 <span style="font-weight:bold; color:${isSkipped ? '#64748b' : evalItem?.correct ? '#16a34a' : '#dc2626'}">${isSkipped ? '○ Not Attempted' : evalItem?.correct ? '✓ Correct' : '✗ Incorrect'}</span>
  </div>
          <div>${qImgsHtml}</div>
          <div>${parsedOptsHtml}</div>
          <div class="dh-review-explanation" style="margin-top:14px; padding:12px; background:#f8fafc; border-left:4px solid #2563eb; font-size:14px; color:#334155;">
            <strong>Explanation:</strong><br/>${evalItem?.solution || 'No explanation provided.'}
  </div>
  </div>`;
    }).join('');

    dh_injectAndRenderDashboardUI(rawScore, reportRowsHtml, fullResponseReviewCardsHtml, calculatedPercentage, safePrintFileName, cls, chSelected, stSelected, nameInput, emailInput, trackingMatrix, timeTakenSeconds, timeTakenFormatted);
  }


