  function injectGitHubAssets() {
    const GITHUB_USER = "debasishsahoolive-design";
    const GITHUB_REPO = "src";
    const GITHUB_BRANCH = "main";
    const BASE_URL = `https://cdn.jsdelivr.net/gh/${GITHUB_USER}/${GITHUB_REPO}@${GITHUB_BRANCH}/`;

    // Matches {[{pic ch01/12}]} or {[{pic ch01/Q12}]} or {[{pic 12}]} or {[{pic Q12}]} or {[{picQ12}]}
    const shortcodeRegex = /\{\[\}\{\[\}\s*pic\s*([A-Za-z0-9_\-\/]+)\s*(?:\{\]\}\{\]\})/gi;
    const cards = document.querySelectorAll('.quiz-card, .dh-report-card-review');

    if (cards.length === 0) {
      setTimeout(injectGitHubAssets, 40);
      return;
    }

    function resolveAssetPath(rawPath) {
      const parts = rawPath.trim().split('/');
      let fileName = parts.pop();
      const dirPath = parts.join('/');

      const normalized = (fileName.startsWith('Q') || fileName.startsWith('q'))
        ? fileName
        : 'Q' + fileName;

      const file = `pic${normalized}.svg`;
      return dirPath ? `${dirPath}/${file}` : file;
    }

    cards.forEach(card => {
      // 1. Process Question Diagrams (Targets live test .q-text and review card containers)
      const qText = card.querySelector('.q-text') || card.querySelector('div:first-child');
      if (qText && shortcodeRegex.test(qText.innerHTML)) {
        qText.innerHTML = qText.innerHTML.replace(shortcodeRegex, (match, pathCode) => {
          const fullFilePath = resolveAssetPath(pathCode);
          return `
            <div class="structural-diagram-box" style="margin: 12px auto; text-align: center; max-width: 500px;">
              <img src="${BASE_URL}${fullFilePath}" alt="${fullFilePath}" style="width: 100%; height: auto; display: block;" loading="lazy" />
            </div>
          `;
        });
      }

      // 2. Process Option Diagrams
      const optionLabels = card.querySelectorAll('.option-label span, .option-text');
      optionLabels.forEach(label => {
        if (shortcodeRegex.test(label.innerHTML)) {
          label.innerHTML = label.innerHTML.replace(shortcodeRegex, (match, pathCode) => {
            const fullFilePath = resolveAssetPath(pathCode);
            return `
              <span class="option-diagram" style="display: inline-block; vertical-align: middle; margin: 4px 6px;">
                <img src="${BASE_URL}${fullFilePath}" alt="${fullFilePath}" style="max-height: auto; width: 70%; vertical-align: middle;" loading="lazy" />
              </span>
            `;
          });
        }
      });
    });

    const container = document.querySelector('.quiz-container');
    if (container) {
      container.classList.add('app-ready');
    }
  }

  function printSummaryOnly() {
    document.body.classList.add('print-summary-only');

    const ch = localStorage.getItem("dh_chapter") || document.getElementById("dh-chapter-select")?.value || "Chapter";
    const st = localStorage.getItem("dh_set") || document.getElementById("dh-set-select")?.value || "Set";
    const student = localStorage.getItem("dh_student_name") || document.getElementById("dh-student-name")?.value || "Student";

    const chapterName = ch.replace(/[\s:]+/g, '_');
    const setName = st.replace(/[\s:]+/g, '_');
    const studentName = student.replace(/[\s]+/g, '_');

    const summaryFileName = `${chapterName}_${setName}_${studentName}`;

    dh_triggerSecurePrint('dh-summary-report-card-panel', summaryFileName);

    setTimeout(() => {
      document.body.classList.remove('print-summary-only');
    }, 500);
  }

function printFullReview() {
    const ch = localStorage.getItem("dh_chapter") || document.getElementById("dh-chapter-select")?.value || "Chapter";
    const st = localStorage.getItem("dh_set") || document.getElementById("dh-set-select")?.value || "Set";
    const student = localStorage.getItem("dh_student_name") || document.getElementById("dh-student-name")?.value || "Student";

    const chapterName = ch.replace(/[\s:]+/g, '_');
    const setName = st.replace(/[\s:]+/g, '_');
    const studentName = student.replace(/[\s]+/g, '_');

    const reviewFileName = `FullReview_${chapterName}_${setName}_${studentName}`;

    // Pass BOTH panels: summary transcript first, then full questions review
    dh_triggerSecurePrint(['dh-summary-report-card-panel', 'dh-full-review-report-panel'], reviewFileName);
  } 
  
function dh_triggerSecurePrint(printTargetElementIds, targetFileNameString) {
    const originalDocumentTitle = document.title;
    const d = new Date();
    const pad = (n) => String(n).padStart(2, '0');
    const timestamp = d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()) + "_" + pad(d.getHours()) + pad(d.getMinutes()) + pad(d.getSeconds());

    document.title = `${targetFileNameString}_${timestamp}`;

    // Support both a single ID string or an array of IDs
    const idList = Array.isArray(printTargetElementIds) ? printTargetElementIds : [printTargetElementIds];
    let combinedHTML = "";

    idList.forEach(id => {
      const el = document.getElementById(id);
      if (el) {
        combinedHTML += el.outerHTML;
      }
    });

    if (!combinedHTML) return;

    // Use isolated iframe to prevent whole page bleed
    let printIframe = document.getElementById('dh-print-frame');
    if (!printIframe) {
      printIframe = document.createElement('iframe');
      printIframe.id = 'dh-print-frame';
      printIframe.style.position = 'fixed';
      printIframe.style.right = '0';
      printIframe.style.bottom = '0';
      printIframe.style.width = '0';
      printIframe.style.height = '0';
      printIframe.style.border = '0';
      document.body.appendChild(printIframe);
    }

    const frameDoc = printIframe.contentWindow.document;
    frameDoc.open();
    frameDoc.write(`
      <!DOCTYPE html>
      <html>
      <head>
        <title>${document.title}</title>
        <style>
          body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
            padding: 24px;
            color: #1e293b;
            background: #ffffff;
          }
          #dh-summary-report-card-panel { max-width:100%; border:1px solid #d7e0eb !important; border-radius:12px !important; }
          .dh-report-brand-header { display:flex; align-items:center; gap:12px; padding-bottom:14px; margin-bottom:16px; border-bottom:2px solid #dbe4f0; }
          .dh-report-ds-logo { display:block; width:60px; height:60px; object-fit:contain; border:0; border-radius:0; background:transparent; margin:0; padding:0; }
          .dh-report-brand-name { margin:0 0 4px; color:#102a43; font-size:16px; font-weight:800; }
          .dh-report-brand-subtitle { margin:0; color:#64748b; font-size:10px; letter-spacing:.08em; text-transform:uppercase; }
          table { width: 100%; border-collapse: collapse; margin-bottom: 24px; }
          th, td { border: 1px solid #cbd5e1; padding: 8px 10px; text-align: center !important; vertical-align: middle !important; }
          #dh-summary-report-card-panel table { table-layout: fixed !important; width: 100% !important; }
          #dh-summary-report-card-panel table th, #dh-summary-report-card-panel table td { width: 25%; text-align: center !important; vertical-align: middle !important; }
          th { background: #1e293b; color: #ffffff; }
          .dh-action-buttons-wrapper, button { display: none !important; }
          img { max-width: 100% !important; height: auto !important; display: block; margin: 14px auto; }
          @page { margin: 15mm; }
        </style>
      </head>
      <body>
        ${combinedHTML}
      </body>
      </html>
    `);
    frameDoc.close();

    // Ensure MathJax renders equations inside iframe if available
    if (printIframe.contentWindow.MathJax && printIframe.contentWindow.MathJax.typesetPromise) {
      printIframe.contentWindow.MathJax.typesetPromise();
    }

    // Wait for images to load before printing
    const imgs = frameDoc.querySelectorAll("img");
    const launchPrint = () => {
      setTimeout(() => {
        printIframe.contentWindow.focus();
        printIframe.contentWindow.print();
        document.title = originalDocumentTitle;
      }, 250);
    };

    if (imgs.length === 0) {
      launchPrint();
    } else {
      let loaded = 0;
      imgs.forEach((img) => {
        if (img.complete) {
          loaded++;
          if (loaded === imgs.length) launchPrint();
        } else {
          img.onload = img.onerror = () => {
            loaded++;
            if (loaded === imgs.length) launchPrint();
          };
        }
      });
    }
  } 


/* Original assessment script 8 */

(function(){
  'use strict';
 var pending=false;
  function guard(){
    pending=false;
    if(!window.matchMedia('(max-width: 700px)').matches)return;
    document.querySelectorAll('.dh-question-body mjx-container, .dh-option-label mjx-container').forEach(function(el){
      if(el.closest('.mh-math-overflow') || el.getAttribute('display')==='true')return;
      var parent=el.parentElement;
      if(!parent || !parent.clientWidth)return;
      /* Inline maths: wrap only if it is actually wider than the available content. */
      if(el.getBoundingClientRect().width <= parent.clientWidth + 2)return;
      var wrapper=document.createElement('span');
      wrapper.className='mh-math-overflow';
      parent.insertBefore(wrapper,el);
      wrapper.appendChild(el);
    });
  }
  function schedule(){if(pending)return;pending=true;requestAnimationFrame(guard);}
  function start(){
    var area=document.querySelector('#dh-dynamic-quiz-card-space');
    if(area){new MutationObserver(schedule).observe(area,{childList:true,subtree:true});}
    schedule();
    window.addEventListener('resize',schedule,{passive:true});
    document.addEventListener('click',function(e){if(e.target.closest('#dh-quiz-nav-panel, #dh-segmented-bar-wrapper'))schedule();});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);
  else start();
})();
